def transform(A, B):
    if len(A) != len(B):
        return -1

    # Count frequency of each character in both strings
    countA = [0] * 256
    countB = [0] * 256

    for char in A:
        countA[ord(char)] += 1

    for char in B:
        countB[ord(char)] += 1

    # Check if both strings have the same characters with the same frequencies
    if countA != countB:
        return -1

    # Calculate the minimum number of operations
    operations = 0
    i = len(A) - 1
    j = len(B) - 1

    while i >= 0 and j >= 0:
        if A[i] == B[j]:
            i -= 1
            j -= 1
        else:
            operations += 1
            i -= 1

    return operations
